//! Embeds the executable icon and version resource (`appres`; assets/icon/pixel-demo.ico, regenerated by
//! `cargo run -p appres --example gen_icon`).

fn main() {
    let dir = std::path::PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    appres::embed_for_build_script(
        &dir.join("../../assets/icon/pixel-demo.ico"),
        "pixel-demo",
        "pixel-demo, demo source for Phoxium",
    );
}
